record.field:
existing_folio = env['x_folios'].search([ ('x_studio_booking', '=', record.id) ], limit=1)
vals = { 'x_studio_booking': record.id, 'x_studio_partner_id': record.x_studio_partner_id.id, 'x_studio_room': record.x_studio_room_no.id, 'x_studio_check_in_1': record.x_studio_check_in, 'x_studio_check_out': record.x_studio_check_out, 'x_studio_value': record.x_studio_value, 'x_studio_no_of_childs': record.x_studio_no_of_childs, 'x_studio_no_of_adults': record.x_studio_no_of_adults, }
if existing_folio: existing_folio.write(vals) else: vals['x_name'] = 'New' env['x_folios'].create(vals)

existing_invoice = env['account.move'].search([
    ('move_type', '=', 'out_invoice'),
    ('x_studio_booking_1', '=', record.id)
], limit=1)

if not existing_invoice:
    invoice = env['account.move'].create({
        'move_type': 'out_invoice',
        'partner_id': record.x_studio_partner_id.id,
        'x_studio_booking_1': record.id,
        'invoice_line_ids': [(0, 0, {
            'name': record.x_name,
            'quantity': 1,
            'price_unit': record.x_studio_value,
        })]
    })

    record.write({
        'x_studio_invoice': invoice.id
    })
else:
    # Keep the existing invoice linked to the booking
    record.write({
        'x_studio_invoice': existing_invoice.id
    })
